function markStreamInfo(kind, patch) {
  state.streamInfo[kind] = { ...state.streamInfo[kind], ...patch }
}

function allStreamsOpen() {
  return streams.mux?.readyState === WebSocket.OPEN && streams.host?.readyState === WebSocket.OPEN
